import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_conversion_rate_none_counts_as_not_converted():
    assert conversion_rate(
        [{"converted": True}, {"converted": None}, {"converted": False}]
    ) == pytest.approx(1 / 3)


def test_conversion_rate_empty_events():
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_each_session():
    groups = {
        "large": [{"converted": True}, {"converted": False}],
        "small": [{"converted": True}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == pytest.approx(2 / 3)


def test_conversions_in_window_uses_last_days_entries():
    assert conversions_in_window([1, 2, 3, 4], 2) == 7
    assert conversions_in_window([1, 2, 3], 0) == 0
    assert conversions_in_window([1, 2, 3], 5) == 6


def test_pooled_conversion_rate_equal_groups():
    groups = {"a": [{"converted": True}, {"converted": False}], "b": [{"converted": True}, {"converted": False}]}
    assert pooled_conversion_rate(groups) == 0.5


def test_parse_session_log_one_line():
    assert parse_session_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "converted": True}]


def test_parse_session_log_flags_whitespace_comments_and_blank_lines():
    assert parse_session_log(
        [" # ignored", " ", " x1 , 3 , 1 ", "x2, 4, 0", "x3,5,"]
    ) == [
        {"id": "x1", "day": 3, "converted": True},
        {"id": "x2", "day": 4, "converted": False},
        {"id": "x3", "day": 5, "converted": None},
    ]


@pytest.mark.parametrize("line", ["x,not-a-day,1", "x,1", "x,1,true"])
def test_parse_session_log_errors_include_input_line(line):
    with pytest.raises(ValueError, match="line 2"):
        parse_session_log(["# skipped", line])


def test_dedupe_sessions_keeps_last_duplicate_id():
    events = [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": 2, "converted": False},
        {"id": "a", "day": 3, "converted": None},
    ]
    assert dedupe_sessions(events) == [events[1], events[2]]


def test_daily_conversion_counts_inclusive_range_and_outside_sessions_ignored():
    events = [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": 2, "converted": True},
        {"id": "c", "day": 2, "converted": None},
        {"id": "d", "day": 4, "converted": True},
    ]
    assert daily_conversion_counts(events, 2, 4) == [1, 0, 1]
    assert daily_conversion_counts(events, 5, 3) == []


def test_group_metrics_and_streak_follow_spec():
    groups = {"z": [], "b": [{"converted": True}], "a": [{"converted": False}]}
    assert conversion_rate_by_group(groups) == {"a": 0.0, "b": 1.0, "z": None}
    assert top_converting_groups(groups, 2) == ["b", "a"]
    assert longest_conversion_streak([1, 2, 0, -1, 3]) == 2


def test_campaign_summary_rounding_and_nonempty_group_count():
    groups = {
        "a": [{"id": "1", "day": 1, "converted": True}],
        "b": [{"id": "2", "day": 3, "converted": False}],
        "empty": [],
    }
    assert campaign_summary(groups, 1) == {"rate": 0.5, "recent": 0, "groups": 2}


def test_campaign_summary_basic():
    e = [{"id": "a", "day": 1, "converted": True}, {"id": "b", "day": 2, "converted": False}]
    assert campaign_summary({"g": e}, 1)["groups"] == 1

