"""Loading and preparing customer-session data."""


def parse_session_log(lines):
    """Parse ``id,day,converted`` lines into session dictionaries.

    Blank lines and lines whose first non-space character is ``#`` are ignored.
    Errors identify the 1-based input line, including skipped lines.
    """
    out = []
    for line_number, line in enumerate(lines, start=1):
        if not line.strip() or line.lstrip().startswith("#"):
            continue

        fields = line.split(",")
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")

        session_id, day_text, converted_text = (field.strip() for field in fields)
        try:
            day = int(day_text)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: day must be an integer") from exc

        if converted_text == "1":
            converted = True
        elif converted_text == "0":
            converted = False
        elif converted_text == "":
            converted = None
        else:
            raise ValueError(f"line {line_number}: converted must be 1, 0, or empty")

        out.append({"id": session_id, "day": day, "converted": converted})
    return out


def dedupe_sessions(events):
    """Keep each id's last session, sorted by day and then id."""
    latest = {}
    for event in events:
        latest[event["id"]] = event
    return sorted(latest.values(), key=lambda event: (event["day"], event["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Count converted sessions for every day in the inclusive date range."""
    if end_day < start_day:
        return []

    counts = {day: 0 for day in range(start_day, end_day + 1)}
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["converted"] is True:
            counts[day] += 1
    return [counts[day] for day in range(start_day, end_day + 1)]
